#!/usr/bin/env bash
# libcss 3rdparty wrapper. Builds NetSurf's MIT-licensed CSS cascade
# (libcss + libparserutils + libwapcaplet) standalone — no GPL'd
# NetSurf core, no other libcurl/xml/png/jpeg/webp deps. The same set
# of three libs is also produced by the netsurf 3rdparty package as a
# side-effect of building netsurf-all; this package is what stays once
# the netsurf prebuilt is dropped.
#
# Shell mapping: reuse the existing netsurf-flavoured shells —
# they carry the deps libcss actually needs (gcc, make, perl,
# pkg-config, plus flex/bison/gperf for libcss's autogenerated
# parser tables, which are NOT in the generic 3rdparty-<platform>
# shells). Coverage matches netsurf's exactly:
#
#   linux-x86_64       → 3rdparty-netsurf            (native)
#   macos-arm64        → 3rdparty-netsurf-macos-arm64 (native)
#   macos-x86_64       → 3rdparty-netsurf-macos-x86_64 (native)
#   linux-aarch64,     → no nix shell — _build.sh's per-platform branch
#   linux-riscv64,       writes a placeholder UNSUPPORTED tarball and
#   android-*, ios-*,    exits 0; the consumer-side libcss.cmake detects
#   tvos-*, webasm,      the marker and skips silently. Cross-compile
#   windows-x86_64       for these targets would need new nix shells
#                        with flex/bison/gperf in the cross sysroot —
#                        deferred until libcss is the only CSS path.
set -euo pipefail
: "${TARGET_PLATFORM:?TARGET_PLATFORM is required}"

case "$TARGET_PLATFORM" in
    linux-x86_64)
        SHELL_NAME="3rdparty-netsurf"
        ;;
    macos-arm64|macos-x86_64)
        SHELL_NAME="3rdparty-netsurf-${TARGET_PLATFORM}"
        ;;
    linux-aarch64|linux-riscv64|\
    android-arm64-v8a|android-x86_64|\
    ios-arm64|ios-x86_64|tvos-arm64|tvos-x86_64|\
    webasm|windows-x86_64)
        # No nix shell — _build.sh's case block writes a placeholder
        # tarball directly. Skip the nix-develop wrapping entirely.
        exec bash "$(dirname "$0")/_build.sh" "$@"
        ;;
    *) echo "unknown TARGET_PLATFORM: $TARGET_PLATFORM" >&2; exit 1 ;;
esac

if [ "${USE_NIX:-1}" = "0" ]; then
    exec bash "$(dirname "$0")/_build.sh" "$@"
fi
cd "$(dirname "$0")/../../.."
exec nix develop ".#$SHELL_NAME" --command bash build-tools/3rdparty/libcss/_build.sh "$@"
